using System;
using System.Collections.Immutable;
using System.Linq;
using ConsoleTables;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Projects")]
    [TestClass]
    public class RJIT_CR_CSPROJ_00001 : ControllerTestBase
    {
        [DataTestMethod]
        [DataRow("Test", "Do not use any test code in your production projects")]
        public void Do_Not_Use_Nuget_Packages(string nugetName, string reason)
        {
            var invalidPackageReferences = (from project in Solution.ProductiveProjects
                                            from package in project.PackageReferences
                                            where package.Include.Contains(nugetName)
                                            select new
                                            {
                                                Project = project.ProjectFileInfo.FileNameWithoutExtenion,
                                                NugetPackage = package.Include,
                                                Reason = reason
                                            }).ToImmutableList();

            Assert.IsTrue(invalidPackageReferences.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00001

Please check that you use recommended nuget packages.{Environment.NewLine}Found: '{invalidPackageReferences.Count}'{Environment.NewLine}{Environment.NewLine}{ConsoleTable.From(invalidPackageReferences)}{Environment.NewLine}");
        }
    }
}
